#include "desktop_ui_logic.h"
#include <iostream>
#include <set>
#include <functional>
using namespace pet;
static int checks=0;
static void check(bool ok,const char*message){++checks;if(!ok)throw std::runtime_error(message);}
static void reject(const std::function<void()>&operation){bool failed=false;try{operation();}catch(...){failed=true;}check(failed,"invalid scale rejected");}
int main(){try{
 Config c;c.timer.mode=Mode::Interval;c.timer.interval=300;c.timer.start(1000);c.timer.tick(1300);c.timer.defer(1300,5);c.x=-900;c.y=80;c.opacity=70;c.scale=150;auto timer=c.timer.json().dump();
 for(int language=0;language<3;++language){c.setLanguage(Language(language));std::set<std::string>names;for(int pet:{0,1,3,4,5,6})for(int coat=0;coat<builtinCoats(pet);++coat){check(c.selectBuiltin(pet,coat),"all appearances selectable");check(names.insert(c.name).second&&!c.name.empty(),"all 22 defaults distinct per language");check(c.timer.json().dump()==timer,"language and role changes never alter timer");}check(names.size()==22,"22 defaults per language");}
 for(int pet:{0,1,3,4,5,6})for(int coat=0;coat<builtinCoats(pet);++coat){c.selectBuiltin(pet,coat);c.rename("Unicode 名前 🐾 "+std::to_string(builtinIdentity(pet,coat)));}
 for(int slot=0;slot<3;++slot){c.profiles[size_t(slot)].files["idle"]=std::string(64,char('a'+slot))+".png";check(c.selectCustom(slot),"custom slot selectable");c.rename("自訂名 "+std::to_string(slot));}
 for(int language=0;language<3;++language){c.setLanguage(Language(language));for(int pet:{0,1,3,4,5,6})for(int coat=0;coat<builtinCoats(pet);++coat){c.selectBuiltin(pet,coat);check(c.name=="Unicode 名前 🐾 "+std::to_string(builtinIdentity(pet,coat)),"custom builtin names stay independent and untranslated");}for(int slot=0;slot<3;++slot){c.selectCustom(slot);check(c.name=="自訂名 "+std::to_string(slot),"three custom names stay independent and untranslated");}}
 auto saved=c.json();Config restored;restored.load(Json::parse(saved.dump()),true);check(restored.json().dump()==saved.dump()&&restored.timer.json().dump()==timer&&restored.x==-900&&restored.scale==150,"all names desktop dialogues and timer survive restart/update");
 restored.selectBuiltin(5,1);restored.resetName();restored.setLanguage(Language::EnUS);check(restored.name==tr(TextId::PetName17,Language::EnUS),"reset follows display language");restored.rename(restored.name);restored.setLanguage(Language::JaJP);check(restored.name==tr(TextId::PetName17,Language::EnUS),"explicitly typing the default pins a user name");restored.selectBuiltin(5,0);check(restored.name=="Unicode 名前 🐾 16","reset does not affect siblings");
 restored.selectCustom(1);restored.resetName();check(restored.name==formatText(TextId::NameCustom,{"2"},Language::JaJP),"reset custom default follows language");restored.setLanguage(Language::EnUS);check(restored.name=="Custom pet 2"&&restored.profiles[0].name=="自訂名 0","custom reset and siblings remain isolated");
 for(int pet:{0,1,3,4,5,6})for(int coat=0;coat<builtinCoats(pet);++coat){Json old;old["pet"]=pet;old["coat"]=coat;old["name"]="舊名稱 日本語";old["builtinName"]="舊名稱 日本語";old["timer"]=c.timer.json();old["language"]="en-US";Config migrated;migrated.load(old,true);check(migrated.name=="舊名稱 日本語"&&migrated.timer.json().dump()==timer,"legacy current name and timer migrate intact");int original=builtinIdentity(pet,coat);for(size_t i=0;i<22;++i)check(migrated.builtinNames[i]==(int(i)==original?"舊名稱 日本語":""),"legacy shared name is captured only for its known appearance");migrated.setLanguage(Language::JaJP);check(migrated.name=="舊名稱 日本語","legacy user name is never translated");}
 Json legacy;legacy["pet"]=2;legacy["builtinName"]="先前內建名稱";legacy["customName"]="小桃";legacy["customFiles"]["idle"]=std::string(64,'a')+".png";Config migrated;migrated.load(legacy,true);check(migrated.name=="小桃"&&migrated.builtinNames[0]=="先前內建名稱","legacy custom and previous builtin name both retained");
 Json invalid;invalid["dialogueEditorWidth"]=100000;invalid["dialogueEditorHeight"]=-9;invalid["builtinNames"]=Json::Array{33,"第二個名字"};Config bounded;bounded.load(invalid,false);check(bounded.dialogueEditorWidth==1600&&bounded.dialogueEditorHeight==320&&bounded.builtinNames[0].empty()&&bounded.builtinNames[1]=="第二個名字"&&bounded.showNameplate,"malformed settings use bounded defaults");bounded.showNameplate=false;Config roundtrip;roundtrip.load(bounded.json(),false);check(!roundtrip.showNameplate,"nameplate preference persists");
 for(int dpi:{96,120,144,192,288,384})for(int width:{480,640,1024,1600})for(int height:{320,480,720,1200})for(int help:{18,40,64}){int w=uiPixels(width,dpi),h=uiPixels(height,dpi);auto layout=dialogueEditorLayout(w,h,dpi,uiPixels(help,dpi));check(contains({0,0,w,h},layout.input)&&contains({0,0,w,h},layout.tabs),"resized editor controls stay inside client");check(!overlaps(layout.input,layout.instructions)&&!overlaps(layout.input,layout.accept)&&!overlaps(layout.preview,layout.accept)&&!overlaps(layout.accept,layout.cancel),"editor explanation, edit and buttons never overlap");check(3*languageTabWidth(layout.tabs.w,dpi)<=layout.tabs.w-uiPixels(8,dpi),"equal tabs fit without horizontal arrows");auto grown=dialogueEditorLayout(w+uiPixels(100,dpi),h+uiPixels(100,dpi),dpi,uiPixels(help,dpi));check(grown.input.w>layout.input.w&&grown.input.h>layout.input.h,"edit area grows on both axes");}
 for(UiRect work:std::array<UiRect,3>{{{-1920,0,1920,1040},{0,0,1920,1040},{-2560,-1440,2560,1400}}})for(int x:{0,100,900})for(int y:{0,100,800}){UiRect pet{work.x+x,work.y+y,144,144};auto plate=accessoryPlacement(pet,work,180,30,2);if(plate)check(contains(work,*plate)&&!overlaps(pet,*plate),"nameplate is stable outside pet and within negative-coordinate work area");auto bubble=accessoryPlacement(pet,work,300,90,4,true,plate);if(bubble)check(contains(work,*bubble)&&!overlaps(pet,*bubble)&&(!plate||!overlaps(*plate,*bubble)),"speech avoids both pet and nameplate");}
 check(!accessoryPlacement({0,0,100,100},{0,0,100,100},90,30,2),"impossible placement does not overlap the pet");
 for(int value=50;value<=300;++value){check(scalePercentage(std::to_wstring(value))==value,"slider/manual percentage roundtrip across full range");}
 for(auto text:{L"",L"49",L"301",L"0",L"-1",L"1000",L"50x",L"５０",L" 50"}){reject([&]{scalePercentage(text);});}
 check(scalePercentage(L"100")==100,"restore size uses the same validation");
 std::cout<<"PASS: "<<checks<<" v1.5.1 checks; 22+3 independent names/migration, localization, editor layout, nameplate placement and scale boundaries\n";return 0;
 }catch(const std::exception&error){std::cerr<<"FAIL: "<<error.what()<<" after "<<checks<<" checks\n";return 1;}}
